/*
 * A057436  Contains digits 1 through 6 only.
 * https://oeis.org/A057436
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nice, nonn, base
 * Formula:   a(n) = the n-th positive integer whose decimal digits are all in
 *            {1,…,6}. // The sequence is generated by enumerating numbers of
 *            increasing length // (1 digit, then 2 digits, …) and, for each
 *            length d, listing all // 6^d numbers in lexicographic order
 *            where each digit is 1‑6. // a(1)=1, a(2)=2, …...
 * Range:     u8 n <= 107, u16 n <= 9059, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

// 
#include <stdint.h>

static idx_t pow6[7] = {1, 6, 36, 216, 1296, 7776, 46656};
static int pow6_initialized = 0;

seq_t a(idx_t n)
{
    if (n < 1) return 0;            /* sequence is defined for n ≥ 1 */

    /* ensure pow6[ ] is initialized – it already contains the
       powers of 6 up to 6^6 but we keep the flag for portability   */
    if (!pow6_initialized) {
        for (idx_t i = 1; i < 7; ++i)
            pow6[i] = pow6[i-1] * 6;
        pow6_initialized = 1;
    }

    /* Find digit length d such that Sum_{i=1}^{d} 6^i ≥ n  */
    idx_t sum = 0;
    idx_t d = 0;
    while (1) {
        ++d;
        sum += pow6[d];
        if (sum >= n) break;
    }

    /* offset of n within the block of length d numbers (0‑based) */
    idx_t prev_sum = sum - pow6[d];
    idx_t offset   = n - prev_sum - 1;   /* 0 ≤ offset < 6^d */

    /* Construct the d‑digit number digit by digit.  Each digit of
       the number is 1 + (offset / 6^i) mod 6   */
    seq_t result = 0;
    for (idx_t i = d; i-- > 0; ) {
        idx_t digit = (offset / pow6[i]) % 6 + 1;
        result = result * 10 + (seq_t)digit;
    }

    return result;
}
